import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const records = vi.hoisted(() => ({ keys: [] as { apiKey: string }[] }));
vi.mock("@/lib/db", async () => ({
  ...await import("@/lib/db/schema"),
  db: { query: { userApiKeys: { findMany: async () => records.keys } } },
}));

import { decodeStoredApiKey, getUserApiKeyForProvider } from "@/lib/byok/keys";

// Generated by encryptApiKey from the preserved main commit 75eb611f, with fake input only.
const legacyCiphertext = "53782c140d1e6a331277df06c7b2fb33:a21d90b6fe85bd7fec863b873fc02162:aecf9b3e0a8015ffe3571493cfe3e4c1f54eb1041a05447d72805e7458e2a75055c7e9586136";
const fixturePlaintext = "legacy-fixture-not-a-real-provider-key";

describe("pre-V2 BYOK ciphertext compatibility", () => {
  beforeEach(() => {
    vi.stubEnv("BETTER_AUTH_SECRET", "legacy-compatibility-fixture-secret-only");
    vi.stubEnv("BYOK_ENCRYPTION_KEY", "");
    records.keys = [{ apiKey: legacyCiphertext }];
  });
  afterEach(() => vi.unstubAllEnvs());

  it("loads a key encrypted by the old release with the retained auth secret", async () => {
    expect(decodeStoredApiKey(legacyCiphertext)).toBe(fixturePlaintext);
    expect(await getUserApiKeyForProvider("existing-user", "kie")).toBe(fixturePlaintext);
  });

  it("preserves the same encrypted format for other stored providers", async () => {
    expect(await getUserApiKeyForProvider("existing-user", "gemini")).toBe(fixturePlaintext);
  });

  it("rejects legacy ciphertext if the original auth secret changes", async () => {
    vi.stubEnv("BETTER_AUTH_SECRET", "different-fixture-secret-only");
    await expect(getUserApiKeyForProvider("existing-user", "kie")).rejects.toThrow("无法解密");
  });

  it("rejects legacy ciphertext under a newly introduced BYOK secret", async () => {
    vi.stubEnv("BYOK_ENCRYPTION_KEY", "different-byok-fixture-secret-only");
    await expect(getUserApiKeyForProvider("existing-user", "kie")).rejects.toThrow("无法解密");
  });

  it("rejects tampered legacy authentication tags", async () => {
    records.keys = [{ apiKey: legacyCiphertext.replace(":a21d", ":b21d") }];
    await expect(getUserApiKeyForProvider("existing-user", "kie")).rejects.toThrow("无法解密");
  });
});
